// This file is generated by AI.

// 文本预处理第 3 步: 给"当前正在配说话者的对话段"加一枚箭头 (Monaco glyph margin)。
//
// 为什么不是只靠选区: 第 3 步的选区是**按光标行推导**出来的 —— 光标一离开对话段
// (比如点到段与段之间的空行) 选区就没了, 而"现在选中的是哪一段"这件事并没有变。
// 箭头挂在那一段的段首行上, 不受光标漂移影响, 也就有了一个稳定的落点。
//
// 形状与实时预览指示器共用 (`editor/block-glyph.ts`), 配色不同 —— 见 styles.css。

import type * as monaco from 'monaco-editor';

import { blockGlyphClassName } from '../editor/block-glyph';

/** 配色类名 (styles.css 里定义形状与颜色) */
const BLOCK_GLYPH_COLOR_CLASS = 'preprocess-block-glyph';
/** 整段高亮的类名 */
const BLOCK_LINE_CLASS = 'preprocess-block-line';

/** 构造装饰区间 (字面量即可满足 `IRange`, 无需 `monaco.Range`) */
function lineRange(startLineNumber: number, startColumn: number, endLineNumber: number, endColumn: number) {
  return { startLineNumber, startColumn, endLineNumber, endColumn };
}

export interface EditorBlockEmphasisRange {
  /** 段首行 (0 基) */
  start: number;
  /** 段末行 (0 基, 闭区间) */
  end: number;
}

interface EditorBlockEmphasisControllerOptions {
  editor: monaco.editor.IStandaloneCodeEditor;
  /** 当前需要强调的行段 (null = 不显示) */
  getRange: () => EditorBlockEmphasisRange | null | undefined;
}

export function createEditorBlockEmphasisController(options: EditorBlockEmphasisControllerOptions) {
  const { editor } = options;
  const decorations = editor.createDecorationsCollection();

  function clear() {
    if (decorations.length === 0) return;
    decorations.clear();
  }

  function sync() {
    const range = options.getRange();
    const model = editor.getModel();
    if (!range || !model) {
      clear();
      return;
    }

    const lineCount = Math.max(1, model.getLineCount());
    const start = Math.min(Math.max(range.start, 0), lineCount - 1) + 1;
    const end = Math.min(Math.max(range.end, range.start), lineCount - 1) + 1;

    decorations.set([
      // 箭头只画在段首行 (零长度区间 => 自动换行时不会每行画一个)
      {
        range: lineRange(start, 1, start, 1),
        options: { glyphMarginClassName: blockGlyphClassName(BLOCK_GLYPH_COLOR_CLASS) },
      },
      // 整段高亮 (一段可能跨多行, 每行都该有底色)
      {
        range: lineRange(start, 1, end, model.getLineMaxColumn(end)),
        options: { className: BLOCK_LINE_CLASS, isWholeLine: true },
      },
    ]);
  }

  // 文档内容变化 (段首行前缀被改写、换行被合并) 后行号会变, 装饰被 Monaco 清掉, 重画一次
  const contentSub = editor.onDidChangeModelContent(() => sync());

  return {
    sync,
    dispose() {
      contentSub.dispose();
      clear();
    },
  };
}
